// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "n", "s"); }
    function testFuzz_property(address ownerActor, uint256 burnAmount) public {
        burnAmount = bound(burnAmount, 0, type(uint256).max/2);

        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(address(this));

        if (beforeBal < burnAmount) {
            uint256 need = burnAmount - beforeBal;
            c.mintToken(address(this), need);
            beforeBal = c.balanceOf(address(this));
            beforeTotal = c.totalSupply();
        }

        bool ok;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterTotal = c.totalSupply();

        if (ok) {
            assertTrue(beforeTotal == afterTotal + burnAmount);
        } else {
            assertTrue(c.totalSupply() == afterTotal);
        }
    }
}
